mapper.select:
SELECT activation_sequence AS activationSequence, directive_id AS directiveId,
       directive_json AS directiveJson, applied_at AS appliedAt
FROM mk_bundle_applied_authorization
WHERE tenant_id=#{key.tenantId} AND environment_name=#{key.environment} AND cell_id=#{key.cell}
  AND campaign_id=#{key.campaignId} AND activation_sequence=#{sequence}

SELECT binding_id AS bindingId, subject_hash AS subjectHash, activation_sequence AS activationSequence,
       participation_json AS participationJson, created_by AS createdBy, created_at AS createdAt
FROM mk_bundle_participation
WHERE tenant_id=#{key.tenantId} AND environment_name=#{key.environment} AND cell_id=#{key.cell}
  AND campaign_id=#{key.campaignId} AND participation_id=#{participationId}
